          this.totalItems = this.tableData.length;
          this.overallTransactions = result.overal_transactions;
          this.updateSummaryData();
          this.tableLoading = false;
        } else {
          this.tableData = [];
          this.overallTransactions = result.overal_transactions || null;
          this.totalItems = 0;
          this.tableLoading = false;
        }
